{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPDC4hWB97D9a17/JK6JGew"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":12,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"Kas6nO6MDic0","executionInfo":{"status":"ok","timestamp":1795146840490,"user_tz":360,"elapsed":65,"user":{"displayName":"Rafael Romero","userId":"14118031302866245531"}},"outputId":"17b6a15c-bc21-498a-e6e4-bdef9e51f62e"},"outputs":[{"output_type":"stream","name":"stdout","text":["Registros brutos cargados: 768\n","Dataset curado v1.0 guardado: 264 registros válidos.\n"]}],"source":["import pandas as pd\n","import numpy as np\n","from pathlib import Path\n","import hashlib\n","\n","def run_pipeline():\n","    # 1. EXTRACT: Lectura de datos crudos inmutables\n","    df_raw = pd.read_csv(\"datos_crudos/diabetes_raw.csv\")\n","    print(f\"Registros brutos cargados: {len(df_raw)}\")\n","\n","    # 2. TRANSFORM: Auditoría de integridad y anonimización\n","    df_clean = df_raw.drop_duplicates().copy()\n","\n","    # Generar ID seudonimizado (SHA-256) para proteger privacidad (PII)\n","    df_clean[\"id_paciente_hash\"] = [\n","        hashlib.sha256(f\"PAC_{i}\".encode()).hexdigest()[:16]\n","        for i in range(len(df_clean))\n","    ]\n","\n","    # Reemplazar ceros biológicamente inverosímiles por NaN reales\n","    cols_biometricas = [\"Glucosa\", \"Presion\", \"IMC\", \"Edad\", \"Diagnostico\"]\n","    df_clean[cols_biometricas] = df_clean[cols_biometricas].replace(0, np.nan)\n","\n","    # Documentar y filtrar registros sin variable clave (Glucosa o IMC)\n","    df_clean = df_clean.dropna(subset=[\"Glucosa\", \"IMC\", \"Diagnostico\"])\n","\n","    # Estratificación bajo estándares clínicos (ADA / OMS)\n","    df_clean[\"Nivel_Glucosa_ADA\"] = pd.cut(\n","        df_clean[\"Glucosa\"],\n","        bins=[0, 99.9, 125.9, 500],\n","        labels=[\"Normal\", \"Prediabetes\", \"Rango_Diabetico\"]\n","    )\n","    df_clean[\"Nivel_IMC_OMS\"] = pd.cut(\n","        df_clean[\"IMC\"],\n","        bins=[0, 24.9, 29.9, 100],\n","        labels=[\"Normal\", \"Sobrepeso\", \"Obesidad\"]\n","    )\n","\n","    # 3. LOAD: Exportar dataset curado v1.0\n","    Path(\"datos_curados\").mkdir(exist_ok=True)\n","    df_clean.to_csv(\"datos_curados/diabetes_v1.0.csv\", index=False)\n","    print(f\"Dataset curado v1.0 guardado: {len(df_clean)} registros válidos.\")\n","\n","if __name__ == \"__main__\":\n","    run_pipeline()"]}]}